local function celestia1()
    print("celestia1 is called") -- 调试信息
    local OldCelestia = CS.UnityEngine.GameObject.Find("/StageRoot/LoginScene(Clone)/SceneObj")
    if OldCelestia then
        CS.MoleMole.ActorUtils.ShowMessage("Found OldCelestia") -- 调试信息
        OldCelestia:SetActive(false)
        Celestia = CS.UnityEngine.Object.Instantiate(OldCelestia)
        Celestia.transform.name = "Celestia"
        Celestia:SetActive(false)
        OldCelestia:SetActive(true)
        CS.UnityEngine.Object.DontDestroyOnLoad(Celestia)
    else
        CS.MoleMole.ActorUtils.ShowMessage("OldCelestia not found") -- 调试信息
    end
end

local function celestia2()
    print("celestia2 is called") -- 调试信息
    local BigWorld = CS.UnityEngine.GameObject.Find("/BigWorld(Clone)")
    if BigWorld and Celestia then
        CS.MoleMole.ActorUtils.ShowMessage("Found BigWorld and Celestia") -- 调试信息
        Celestia:SetActive(true)
        CS.UnityEngine.Object.Destroy(CS.UnityEngine.GameObject.Find("/Celestia/ModelCamera"))

        local StartPos = CS.MoleMole.ActorUtils.GetAvatarPos()
        local NewPos = CS.UnityEngine.Vector3(StartPos.x, 1000.0, StartPos.z)
        CS.MoleMole.ActorUtils.SetAvatarPos(NewPos)
        BigWorld:SetActive(false)
        local cord = CS.UnityEngine.Vector3(StartPos.x, 500.0, StartPos.z)
        Celestia.transform.GetChild(1).position = cord
        Celestia.transform.GetChild(2).position = cord
    else
        CS.MoleMole.ActorUtils.ShowMessage("BigWorld or Celestia not found") -- 调试信息
    end
end
local function test()
    local canvas = CS.UnityEngine.GameObject.Find("/Canvas")
    local moonlight1 = CS.UnityEngine.GameObject("moonlight1")
    local moonlight2 = CS.UnityEngine.GameObject("moonlight2")
    local x = 1080
    local y = 1080
    -- add button to panel
    local button1 = moonlight1:AddComponent(typeof(CS.UnityEngine.UI.Button))
    local button2 = moonlight2:AddComponent(typeof(CS.UnityEngine.UI.Button))
    CS.UnityEngine.Object.DontDestroyOnLoad(moonlight1)
CS.UnityEngine.Object.DontDestroyOnLoad(moonlight2)

    CS.UnityEngine.Object.DontDestroyOnLoad(canvas)
    button1.onClick:AddListener(celestia1)
    button2.onClick:AddListener(celestia2)

    -- load image
    local image1 = moonlight1:AddComponent(typeof(CS.UnityEngine.UI.Image))
    local image2 = moonlight2:AddComponent(typeof(CS.UnityEngine.UI.Image))
    local texture = CS.UnityEngine.Texture2D(x, y)
    bytes = CS.System.Convert.FromBase64String("")
    CS.UnityEngine.ImageConversion.LoadImage(texture, bytes)
    image1.sprite = CS.UnityEngine.Sprite.Create(texture, CS.UnityEngine.Rect(0, 0, x, y), CS.UnityEngine.Vector2(0.5, 0.5))
    image1:SetNativeSize()
    image2.sprite = CS.UnityEngine.Sprite.Create(texture, CS.UnityEngine.Rect(0, 0, x, y), CS.UnityEngine.Vector2(0.5, 0.5))
    image2:SetNativeSize()
    moonlight1.transform:SetParent(canvas.transform, false)
moonlight2.transform:SetParent(canvas.transform, false)
    moonlight1.transform.localPosition = CS.UnityEngine.Vector3(380, 865, 5)
    moonlight1.transform.localScale = CS.UnityEngine.Vector3(0.6, 0.6, 0.6)
    local rectTransform1 = moonlight1:GetComponent(typeof(CS.UnityEngine.RectTransform))
    rectTransform1.anchorMin = CS.UnityEngine.Vector2(0, 0)
    rectTransform1.anchorMax = CS.UnityEngine.Vector2(0, 0)
    rectTransform1.sizeDelta = CS.UnityEngine.Vector2(100, 100)

    moonlight2.transform.localPosition = CS.UnityEngine.Vector3(500, 865, 5)
    moonlight2.transform.localScale = CS.UnityEngine.Vector3(0.6, 0.6, 0.6)
    local rectTransform2 = moonlight2:GetComponent(typeof(CS.UnityEngine.RectTransform))
    rectTransform2.anchorMin = CS.UnityEngine.Vector2(0, 0)
    rectTransform2.anchorMax = CS.UnityEngine.Vector2(0, 0)
    rectTransform2.sizeDelta = CS.UnityEngine.Vector2(100, 100)
end



test()